  ('cineplanet', 'Cineplanet — Combos y Entradas', 'special', '/library/cineplanet.webp', null, '{}'::text[], '{}'::text[], array['cine','peliculas','combos','entradas','canchita','popcorn']::text[], '{}'::text[], '[{"title": "Cómo comprar", "kind": "steps", "items": ["Indícanos qué necesitas: entrada, combo o ambos", "Dinos la sede de Cineplanet y la película que quieres ver", "Si necesitas horarios, te generamos el mensaje para solicitarlos", "Te confirmamos el precio según tu sede", "Realizas el pago por YAPE o PLIN", "Hacemos la compra en tu nombre y te enviamos el QR por WhatsApp", "Presentas el QR en la dulcería o boletería — ¡listo!"]}, {"title": "Importante", "kind": "note", "items": ["Los combos deben usarse el mismo día de la compra — no son válidos para otra fecha", "El descuento en entradas es de hasta 50% — el porcentaje exacto varía según sede y función", "Los precios varían por ciudad y sede — siempre consultamos antes de cobrar"]}, {"title": "¿Cómo funciona el refill de la canchita?", "kind": "steps", "items": ["Al recoger tu combo en la dulcería, te entregarán un voucher", "Guarda ese voucher durante la película", "Cuando quieras recargar tu canchita, preséntalo en dulcería", "Recibe tu recarga gratis — válido 1 sola vez por combo"]}, {"title": "Combos", "kind": "list", "items": ["Combo Oro Personal: Canchita mediana, Gaseosa mediana, 1 refill de canchita gratis", "Combo Oro Dúo: 2 canchitas medianas, 2 gaseosas medianas, 1 refill por canchita gratis", "Combo Black Personal: Canchita mediana, Gaseosa mediana, Nachos o hot dog a elección, 1 refill de canchita gratis", "Combo Black Gigante: Canchita gigante, 2 gaseosas medianas, Nachos o hot dog a elección, 1 refill de canchita gratis"]}]'::jsonb, 160),
