-- Biblioteca global de plataformas. Re-ejecutable.
on conflict (id) do update set name = excluded.name, category_key = excluded.category_key, logo_url = excluded.logo_url, description = excluded.description, features = excluded.features, restrictions = excluded.restrictions, tags = excluded.tags, popular_content = excluded.popular_content, extra_sections = excluded.extra_sections, sort = excluded.sort, updated_at = now();
